import{_ as l,a0 as p,w as r,s as d,ao as o,I as n,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何隐藏你的 Linux 的命令行历史 | LCTT x X-CMD","titleTemplate":false,"description":"如何隐藏你的 Linux 的命令行历史 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何隐藏你的 Linux 的命令行历史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何隐藏你的 Linux 的命令行历史 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160625 How to Hide Linux Command Line History by Going Incognito","title":"如何隐藏你的 Linux 的命令行历史","tag":"201607","desc":""},"relativePath":"201607/20160625 How to Hide Linux Command Line History by Going Incognito.md","filePath":"[post].md"}'),h={name:"201607/20160625 How to Hide Linux Command Line History by Going Incognito.md"};function g(u,i,c,k,m,b){const e=p("Link");return r(),d("div",null,[i[16]||(i[16]=o('<h1 id="如何隐藏你的-linux-的命令行历史" tabindex="-1">如何隐藏你的 Linux 的命令行历史 <a class="header-anchor" href="#如何隐藏你的-linux-的命令行历史" aria-label="Permalink to “如何隐藏你的 Linux 的命令行历史”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-featured.jpg" alt=""></p><p>如果你是 Linux 命令行的用户，有的时候你可能不希望某些命令记录在你的命令行历史中。原因可能很多，例如，你在公司担任某个职位，你有一些不希望被其它人滥用的特权。亦或者有些特别重要的命令，你不希望在你浏览历史列表时误执行。</p><p>然而，有方法可以控制哪些命令进入历史列表，哪些不进入吗？或者换句话说，我们在 Linux 终端中可以开启像浏览器一样的无痕模式吗？答案是肯定的，而且根据你想要的具体目标，有很多实现方法。在这篇文章中，我们将讨论一些行之有效的方法。</p><p>注意：文中出现的所有命令都在 Ubuntu 下测试过。</p><h3 id="不同的可行方法" tabindex="-1">不同的可行方法 <a class="header-anchor" href="#不同的可行方法" aria-label="Permalink to “不同的可行方法”">​</a></h3>',6)),n("p",null,[i[1]||(i[1]=s("前面两种方法已经在之前",-1)),a(e,{href:"https://www.maketecheasier.com/command-line-history-linux/"},{default:t(()=>[...i[0]||(i[0]=[s("一篇文章",-1)])]),_:1}),i[2]||(i[2]=s("中描述了。如果你已经了解，这部分可以略过。然而，如果你不了解，建议仔细阅读。",-1))]),i[17]||(i[17]=o('<h4 id="_1-在命令前插入空格" tabindex="-1">1. 在命令前插入空格 <a class="header-anchor" href="#_1-在命令前插入空格" aria-label="Permalink to “1. 在命令前插入空格”">​</a></h4><p>是的，没看错。在命令前面插入空格，这条命令会被 shell 忽略，也就意味着它不会出现在历史记录中。但是这种方法有个前提，只有在你的环境变量 <code>HISTCONTROL</code> 设置为 &quot;ignorespace&quot; 或者 &quot;ignoreboth&quot; 才会起作用。在大多数情况下，这个是默认值。</p><p>所以，像下面的命令（LCTT 译注：这里<code>[space]</code>表示输入一个空格）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[space]echo &quot;this is a top secret&quot;</span></span></code></pre></div><p>如果你之前执行过如下设置环境变量的命令，那么上述命令不会出现在历史记录中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL = ignorespace</span></span></code></pre></div><p>下面的截图是这种方式的一个例子。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-bash-command-space.png" alt=""></p><p>第四个 &quot;echo&quot; 命令因为前面有空格，它没有被记录到历史中。</p><h4 id="_2-禁用当前会话的所有历史记录" tabindex="-1">2. 禁用当前会话的所有历史记录 <a class="header-anchor" href="#_2-禁用当前会话的所有历史记录" aria-label="Permalink to “2. 禁用当前会话的所有历史记录”">​</a></h4><p>如果你想禁用某个会话所有历史，你可以在开始命令行工作前简单地清除环境变量 HISTFILESIZE 的值即可。执行下面的命令来清除其值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTFILESIZE=0</span></span></code></pre></div><p>HISTFILESIZE 表示对于 bash 会话其历史文件中可以保存命令的个数（行数）。默认情况，它设置了一个非零值，例如在我的电脑上，它的值为 1000。</p><p>所以上面所提到的命令将其值设置为 0，结果就是直到你关闭终端，没有东西会存储在历史记录中。记住同样你也不能通过按向上的箭头按键或运行 history 命令来看到之前执行的命令。</p><h4 id="_3-工作结束后清除整个历史" tabindex="-1">3. 工作结束后清除整个历史 <a class="header-anchor" href="#_3-工作结束后清除整个历史" aria-label="Permalink to “3. 工作结束后清除整个历史”">​</a></h4><p>这可以看作是前一部分所提方案的另外一种实现。唯一的区别是在你完成所有工作之后执行这个命令。下面是刚说到的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history -cw</span></span></code></pre></div><p>刚才已经提到，这个和 HISTFILESIZE 方法有相同效果。</p><h4 id="_4-只针对你的工作关闭历史记录" tabindex="-1">4. 只针对你的工作关闭历史记录 <a class="header-anchor" href="#_4-只针对你的工作关闭历史记录" aria-label="Permalink to “4. 只针对你的工作关闭历史记录”">​</a></h4><p>虽然前面描述的方法（2 和 3）可以实现目的，它们可以清除整个历史，在很多情况下，有些可能不是我们所期望的。有时候你可能想保存直到你开始命令行工作之间的历史记录。对于这样的需求，你开始在工作前执行下述命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[space]set +o history</span></span></code></pre></div><p>备注：[space] 表示空格。并且由于空格的缘故，该命令本身也不会被记录。</p><p>上面的命令会临时禁用历史功能，这意味着在这命令之后你执行的所有操作都不会记录到历史中，然而这个命令之前的所有东西都会原样记录在历史列表中。</p><p>要重新开启历史功能，执行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Space]set -o history</span></span></code></pre></div><p>它将环境恢复原状，也就是你完成了你的工作，执行上述命令之后的命令都会出现在历史中。</p><h4 id="_5-从历史记录中删除指定的命令" tabindex="-1">5. 从历史记录中删除指定的命令 <a class="header-anchor" href="#_5-从历史记录中删除指定的命令" aria-label="Permalink to “5. 从历史记录中删除指定的命令”">​</a></h4><p>现在假设历史记录中已经包含了一些你不希望记录的命令。这种情况下我们怎么办？很简单。直接动手删除它们。通过下面的命令来删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history | grep &quot;part of command you want to remove&quot;</span></span></code></pre></div><p>上面的命令会输出历史记录中匹配的命令，每一条前面会有个数字。</p><p>一旦你找到你想删除的命令，执行下面的命令，从历史记录中删除那个指定的项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history -d [num]</span></span></code></pre></div><p>下面是这个例子的截图。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-delete-specific-commands.png" alt=""></p><p>第二个 ‘echo’命令被成功的删除了。</p><p>（LCTT 译注：如果你不希望上述命令本身也被记录进历史中，你可以在上述命令前加个空格）</p><p>同样的，你可以使用向上的箭头一直往回翻看历史记录。当你发现你感兴趣的命令出现在终端上时，按下 “Ctrl + U”清除整行，也会从历史记录中删除它。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>有多种不同的方法可以操作 Linux 命令行历史来满足你的需求。然而请记住，从历史中隐藏或者删除命令通常不是一个好习惯，尽管本质上这并没有错。但是你必须知道你在做什么，以及可能产生的后果。</p><hr>',40)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),a(e,{href:"https://www.maketecheasier.com/linux-command-line-history-incognito/"},{default:t(()=>[...i[3]||(i[3]=[s("https://www.maketecheasier.com/linux-command-line-history-incognito/",-1)])]),_:1})]),n("p",null,[i[8]||(i[8]=s("作者：",-1)),a(e,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:t(()=>[...i[5]||(i[5]=[s("Himanshu Arora",-1)])]),_:1}),i[9]||(i[9]=s(" 译者：",-1)),a(e,{href:"https://github.com/chunyang-wen"},{default:t(()=>[...i[6]||(i[6]=[s("chunyang-wen",-1)])]),_:1}),i[10]||(i[10]=s(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[7]||(i[7]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[13]||(i[13]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[11]||(i[11]=[s("LCTT",-1)])]),_:1}),i[14]||(i[14]=s(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...i[12]||(i[12]=[s("Linux中国",-1)])]),_:1}),i[15]||(i[15]=s(" 荣誉推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
